def random_list(n,a,b):
  return [random.randint(a,b) for c in range(n)] #change 0,100 to a,b to limitied the numbers

L = random_list(10,0,100) # I want 10 numbers between 3-20

small = [] #not a function but a cell

for x in L:
  if x < 50:
    small.append(x)
print(small)

small = [] #not a function but a cell

for x in L:
  if x <= 50:
    small.append(x)
print(small)

