"""**conditional list comprehension**"""

[2*x + 1 for x in range(10)] #simple comprehension

[2*x + 1 for x in range(10) if x > 4] #comprehension with if

small = [] #not a function but a cell

for x in L:
  if x < 50:
    small.append(x)
print(small)

"""above is a same idea like below"""

print(L)
small_c = [k for k in L if k < 50] #we have a plus if condition at end
print(small_c)

